// ARGOS engine SIL - valve-map cross-check (v3, 2026-10-12). NOT a generator any more: since v2.5 the ECU feed-forward
// table src/core/valve_map_table.h is generated by tools/gen_tables.py from Combustion's published throttle_map_v2.csv,
// so the SIL plant (Electronics' own model of the same physics) is a model the controller was not tuned on.
// This tool quantifies that difference row by row for the initial port (D_port 0.025 m):
//   ECU   lift from the generated table (ValveMap::lift, the flight code) at the map's Pc and tank pressure
//   SIL   lift at which the SIL plant reaches the map's Pc (steady state, Dyer v2 convention, line loss ~mdot^2)
//   SIL Pc / F at the map's lift
// The v2.1 generator (SIL plant -> table) is archived as tools/archive/gen_valve_map_v2p1.cpp.
// Usage: gen_valve_map <throttle_map_v2.csv> [D_port_m=0.025]  (prints a table; the Makefile tees it to results/)
#include <algorithm>
#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>
#include "control.h"
#include "plant.h"

using namespace sil;

static double Tsat(double P) {   // invert the saturation table
  double lo = 245.0, hi = 307.0;
  for (int i = 0; i < 60; ++i) { const double m = 0.5 * (lo + hi); if (satP(m) > P) hi = m; else lo = m; }
  return 0.5 * (lo + hi);
}

int main(int argc, char** argv) {
  if (argc < 2) { std::fprintf(stderr, "usage: %s throttle_map_v2.csv [D_port_m]\n", argv[0]); return 2; }
  const double dsel = argc >= 3 ? std::atof(argv[2]) : 0.025;
  EngineParams ep;
  EnginePlant eng(ep);
  if (std::fabs(eng.Dport - dsel) > 1e-6) { std::fprintf(stderr, "plant initial port %.4f m != requested %.4f m\n", eng.Dport, dsel); return 2; }
  const double xmax = 4.2e-3;
  auto pcss = [&](double T, double x) { double pc; eng.steadyState(T, x, &pc, nullptr, nullptr, nullptr); return pc; };
  std::ifstream c(argv[1]);
  if (!c.good()) { std::printf("CHECK NOT RUN: cannot read %s\n", argv[1]); return 1; }
  std::printf("valve-map cross-check v3: Combustion throttle_map_v2 (D_port %.3f m) vs ECU table (flight code) vs SIL plant\n", dsel);
  std::printf("%8s %6s %6s %8s | %9s %9s %7s | %9s %7s | %8s %7s %7s %7s\n", "P_tank", "T_K", "F_N", "Pc_bar", "lift_mm",
              "ECU_mm", "dECU%", "SIL_mm", "dSIL%", "SILPc", "dPc%", "SIL_F", "dF%");
  std::string line; std::vector<std::string> hdr;
  double max_ecu = 0, max_sil = 0, max_pc = 0, max_F = 0, sum_pc = 0; int n = 0, n_unreach = 0;
  while (std::getline(c, line)) {
    if (line.empty() || line[0] == '#') continue;
    std::vector<std::string> v; std::stringstream ss(line); std::string tok;
    while (std::getline(ss, tok, ',')) v.push_back(tok);
    if (hdr.empty()) { hdr = v; continue; }
    auto col = [&](const char* name) -> double {
      for (size_t k = 0; k < hdr.size() && k < v.size(); ++k) if (hdr[k] == name) return v[k].empty() ? NAN : std::atof(v[k].c_str());
      return NAN;
    };
    const double D = col("D_port_m");
    if (!(std::fabs(D - dsel) < 1e-6)) continue;
    const double Ptk = col("P_tank_Pa"), T = col("T_tank_K"), F = col("F_N"), Pc = col("Pc_Pa"), h = col("lift_m");
    if (!std::isfinite(Pc) || !std::isfinite(h) || h <= 0) continue;
    const double Tp = std::isfinite(T) ? T : Tsat(Ptk);
    // ECU feed-forward (flight code, generated table)
    const float x_ecu = ecu::ValveMap::lift(static_cast<float>(Pc), static_cast<float>(Ptk), nullptr);
    // SIL lift for the map's Pc
    double x_sil;
    if (pcss(Tp, xmax) < Pc) { x_sil = NAN; ++n_unreach; }
    else {
      double lo = 0, hi = xmax;
      for (int it = 0; it < 50; ++it) { const double m = 0.5 * (lo + hi); if (pcss(Tp, m) > Pc) hi = m; else lo = m; }
      x_sil = 0.5 * (lo + hi);
    }
    double pc2, mo, mf, F2; eng.steadyState(Tp, h, &pc2, &mo, &mf, &F2);
    const double e_ecu = 100.0 * (x_ecu - h) / h, e_sil = 100.0 * (x_sil - h) / h;
    const double e_pc = 100.0 * (pc2 - Pc) / Pc, e_F = 100.0 * (F2 - F) / F;
    max_ecu = std::max(max_ecu, std::fabs(e_ecu));
    if (std::isfinite(e_sil)) max_sil = std::max(max_sil, std::fabs(e_sil));
    max_pc = std::max(max_pc, std::fabs(e_pc)); max_F = std::max(max_F, std::fabs(e_F)); sum_pc += e_pc; ++n;
    std::printf("%8.2f %6.2f %6.1f %8.3f | %9.4f %9.4f %+7.2f | %9.4f %+7.2f | %8.3f %+7.2f %7.1f %+7.2f\n", Ptk / 1e5, Tp, F, Pc / 1e5,
                h * 1e3, x_ecu * 1e3, e_ecu, x_sil * 1e3, e_sil, pc2 / 1e5, e_pc, F2, e_F);
  }
  std::printf("rows %d (D_port %.3f m); SIL cannot reach the map Pc in %d rows\n", n, dsel, n_unreach);
  std::printf("max |ECU table lift - map lift| = %.2f %% (table interpolation, PCHIP in Pc, linear in P_tank)\n", max_ecu);
  std::printf("max |SIL lift - map lift| = %.2f %%; SIL Pc at the map lift: max |error| %.2f %%, mean %+.2f %%; thrust max |error| %.2f %%\n",
              max_sil, max_pc, n ? sum_pc / n : NAN, max_F);
  std::printf("interpretation: the ECU closes the Pc loop (PI + learned trim) around this feed-forward; the SIL plant differs from the\n"
              "map by the amounts above (fuel-law form, port model, line-loss coupling), which the loop must absorb. Neither is a\n"
              "measurement: cold-flow and static-fire characterisation replace both.\n");
  return 0;
}
